import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·31","description":"易小帖 - 卷一·31","frontmatter":{"title":"卷一·31","description":"易小帖 - 卷一·31"},"headers":[],"relativePath":"zh/classics/yixiaotie/031.md","filePath":"zh/classics/yixiaotie/031.md"}'),o={name:"zh/classics/yixiaotie/031.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·31",tabindex:"-1"},[r("卷一·31 "),e("a",{class:"header-anchor",href:"#卷一·31","aria-label":"Permalink to “卷一·31”"},"​")],-1),e("p",null,"「女子貞不字」，「字」字，虞翻、荀爽《九家易》，及唐儒崔憬、李鼎祚諸註本，皆作孕妊解。即《說文》、《玉篇》諸字書，亦只有孕乳撫育二義，故文字之字，亦以子母相生為義可見也。自朱子《本義》，誤引《曲禮》「女子二十許嫁，笄而字」語，遂註曰「許嫁曰字」。夫《曲禮》之字，是名字之字，故上文曰名子者不以國，又曰男子二十冠而字。父前子名，君前臣名，然後曰女子二十笄而字，謂男子成人即不名而字。惟君父前則仍名，而女子亦然。故孔氏《禮疏》謂笄而字者，如《春秋》之稱伯姬、仲姬是也。若曰許嫁，則明儒郭子章有曰：男子二十冠，而許嫁必非禮意。姚承庵有曰：女子許嫁，笄而許嫁，定無是文義。乃不幸元明字書，竟入其說，將漢魏六朝以及唐人凡為墓銘者，並無男娶女字之文，而明代有之予嘗昌言其非。而輓近陋儒，依回兩端，以已嫁者稱適，未嫁者稱未字許字。夫此係經文，且為易禮二書所共係之文，而以此調停陋矣。先仲氏曰：人苦不讀書，《昏禮》雲：女子許嫁稱字，明於字字上加一稱字。《春秋》僖九年，伯姬卒，《公羊》曰：「此未適人，何以卒？許嫁矣。」何以知許嫁？婦人許嫁笄而字之，則明以伯姬之稱而知其許嫁。字者伯姬也。人不識《曲禮》，盍亦就諸經一觀之乎。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
